# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.1/ankra-cli-darwin-arm64"
      sha256 "09b24cdcf3c0bc10cb816d559b316d9b076c3fc4061d734f5062a4e20f035e33"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.1/ankra-cli-darwin-amd64"
      sha256 "36445e636493384b4eea16b5eb8f5d9efc99cedafa803b1cad0bd3aa04abdb11"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.1/ankra-cli-linux-arm64"
      sha256 "3f9feedb7f0732ce7f12d475e2911ea51dfc65dba7c8abf6c15eeeb055c6d2c5"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.52.1/ankra-cli-linux-amd64"
